private renderUnifiedLcnRow(row: UnifiedLcnRow, favs: string[], position: number, top: number): Safe {
  const channel = row.channel;
  const idx = row.channelIndex;
  const isPlaying = idx >= 0 && idx === this.playingIndex && this.playingCatchupStart === null;
  const favorite = channel ? favs.includes(channelKey(channel)) : false;
  const epgId = channel ? EpgService.findChannelId(channel) : null;
  const nowPlaying = epgId ? EpgService.getNowPlaying(epgId) : null;
  const state = idx >= 0
    ? (row.entry.kind === 'CANDIDATO_DA_COLLAUDARE' ? 'IPTV da provare'
      : row.entry.kind === 'CANDIDATO_SIMULCAST' ? 'IPTV simulcast' : 'IPTV in lista')
    : row.entry.kind === 'ESCLUSO_NON_FUNZIONANTE'
      ? 'IPTV già non funzionante' : 'Nessuno stream IPTV verificato';
  return html`
    <div class="channel-item ${isPlaying ? 'playing' : ''} ${idx < 0 ? 'montecrestese-no-stream' : ''}"
         data-key="lcn:${row.entry.lcn}" data-focusable
         data-unified-lcn="${row.entry.lcn}" data-list-position="${position}" style="top:${top}px">
      <div class="channel-number">${row.entry.lcn}</div>
      ${channel ? this.renderLogo(channel) : html`<div class="channel-logo-wrap"><div class="channel-logo-placeholder">${row.entry.name.charAt(0)}</div></div>`}
      <div class="channel-info">
        <div class="channel-name">${favorite ? raw(favoriteIcon(true)) : ''}${row.entry.name}</div>
        <div class="channel-now montecrestese-lcn-state">${state}${nowPlaying ? ' · ' + nowPlaying.title : ''}</div>
      </div>
      ${channel ? this.renderHealth(channel) : ''}
      ${isPlaying ? raw('<div class="playing-indicator">&#9654;</div>') : ''}
    </div>
  `;
}

