  it('shows 85 virtual positions in Diretta, with one OK for IPTV and safe fallback for TV8/Videogruppo', () => {
    const original = data.channels.map(ch => ch.channelNumber);
    data.channels[0].channelNumber = 13;
    data.channels[1].channelNumber = 83;
    data.channels[2].channelNumber = 6;
    const onOpenHybridLcn = vi.fn();
    try {
      list = new ChannelList(container, {
        onChannelSelect: onSelect, onOpenHybridLcn, enableUnifiedLcn: true,
      });
      list.render();
      expect(container.querySelector('.channel-count')?.textContent).toContain('85');
      expect(container.querySelector('.channel-list-spacer')?.getAttribute('style')).toContain('height:');
      const tv8 = container.querySelector<HTMLElement>('[data-unified-lcn="8"]');
      const videogruppo = container.querySelector<HTMLElement>('[data-unified-lcn="12"]');
      expect(tv8?.textContent).toContain('TV8');
      expect(videogruppo?.textContent).toContain('Videogruppo');
      (list as unknown as { nav: { focus: (el: HTMLElement) => void } }).nav.focus(tv8!);
      list.handleAction('select');
      expect(onOpenHybridLcn).toHaveBeenCalledWith(8);
      expect(onSelect).not.toHaveBeenCalled();
      const rete7 = container.querySelector<HTMLElement>('[data-unified-lcn="13"]');
      (list as unknown as { nav: { focus: (el: HTMLElement) => void } }).nav.focus(rete7!);
      list.handleAction('select');
      expect(onSelect).toHaveBeenCalledWith(0, undefined, expect.anything(), 'expand-current');
      expect(onOpenHybridLcn).toHaveBeenCalledTimes(1);
